#!/usr/bin/env bash
# Claude Code PreToolUse hook (Bash), wired in .claude/settings.json. Holds
# the rules AGENTS.md states and an agent can forget:
#   - no commits or pushes unless the user asked: `git commit` and
#     `git push` ask the user first;
#   - golden files are regenerated by their tests, never written by a shell
#     command (before-edit.sh refuses the edit tools);
#   - no AI attribution: a commit message naming Claude as co-author is
#     refused (scripts/git-hooks/commit-msg refuses it too);
#   - no broad kills: `pkill -f` and `killall` are refused. `pkill -f cat`
#     once matched every process under /Applications.
set -uo pipefail

command -v jq >/dev/null || exit 0
cmd="$(jq -r '.tool_input.command // empty')"

decide() {
  jq -n --arg d "$1" --arg r "$2" \
    '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: $d, permissionDecisionReason: $r}}'
  exit 0
}

if grep -Eiq 'co-authored-by:.*(claude|anthropic)|generated with \[?claude' <<<"$cmd"; then
  decide deny "No AI attribution in commits or PRs (AGENTS.md). Remove the Co-Authored-By / Generated-with line."
fi
# Only where a command starts (a line, or after ; & | or $( ), so a commit
# message or a grep that mentions them passes.
if grep -Eq '(^|[;&|]|\$\()[[:space:]]*(sudo[[:space:]]+)?(pkill[[:space:]]+(-[a-zA-Z]*f|--full)|killall)([[:space:]]|$)' <<<"$cmd"; then
  decide deny "No broad kills: find the PID you started (pgrep -fl, then check it) and kill that PID only."
fi
# A write aimed at a golden file: a redirect into it, or an in-place editor,
# copy or move naming it. Reading one (cat, diff, grep) passes.
if grep -Eq '(>|tee([[:space:]]+-a)?)[[:space:]]*[^[:space:]]*\.golden(\.json)?([[:space:]]|$)|(sed[[:space:]]+-i|perl[[:space:]]+-p?i|(^|[;&|[:space:]])(cp|mv|truncate))[^;&|]*\.golden(\.json)?([[:space:]]|$)' <<<"$cmd"; then
  decide deny "Golden files are generated: regenerate with UPDATE_GOLDEN=1 go test ./e2eTest -run 'TestSnapshotSchema|TestScanDigest' and review the diff (AGENTS.md)."
fi
if grep -Eq '(^|[;&|[:space:]])git([[:space:]]+-[cC][[:space:]]+[^[:space:]]+)*[[:space:]]+(commit|push)([[:space:]]|$)' <<<"$cmd"; then
  decide ask "AGENTS.md: no commits or pushes unless the user asked for one."
fi
exit 0
